import {paperResultLesson} from './paper-results.js';
// Lessons 5–12: one small example, then an equation, a test, and a source task.
const raw=String.raw;
const example=(title,html)=>`<aside class="worked-example"><div class="example-kicker">WORKED TOY EXAMPLE</div><h3>${title}</h3>${html}</aside>`;
const bridge=(question,metric,task)=>`<div class="metric-bridge"><strong>From principle to measurement</strong><p><b>Question:</b> ${question}</p><p><b>Measure:</b> ${metric}</p><p><b>Try it on:</b> ${task}</p></div>`;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const repo=(name,path='')=>{const sources={particles:['nchopin/particles','3388c4bd30ab9acc5a27c970089230f93610b627'],stonesoup:['dstl/Stone-Soup','d6c2d5713b5fdc0bc0c5c0226898bc1c598a882a'],cuthbert:['state-space-models/cuthbert','c737efe3098b2b5ecaa7d8b976e7cea246998b17'],pfjax:['mlysy/pfjax','97652aa1bdff73a92c0286549b010e99cc6f7264'],pydpf:['John-JoB/pydpf','a7487ce1c344c70e1a244e75725b950deb15e146'],filterflow:['JTT94/filterflow','5d8300ba247c4c17e1a301a22560c24fd0670bfe'],torchfilter:['stanford-iprl-lab/torchfilter','4a8a085f6406ec07ce6a701e7d8cb4c62c97a390'],julia:['skarppinen/Resamplings.jl','5cc4dd050c568abd8aedc45c6dbe318b0bc6ec7f']};const[r,c]=sources[name];return`<a href="https://github.com/${r}/tree/${c}/${path}" target="_blank" rel="noopener noreferrer">${r}${path?' · '+path:''} ↗</a>`;};
export function advancedLessons(references,glossary){return[
{id:'claims',group:'DESIGN THE METHOD',title:'Our research claims',subtitle:'Start with what a probability estimate must do.',goal:'Build a precise claim from a two-particle example, then choose a test that can disprove it.',sections:[
{id:'first-principle',title:'First principle: preserve answers to questions',html:raw`<p>A probability distribution lets us answer questions about an unknown state. “Where is its center?” is one question. “How likely is a dangerous position?” is another. A resampler changes the finite representation of that distribution. We need to say which answers it should preserve.</p><p>Write a question as a <strong>test function</strong> \(f\). Its weighted answer is an expectation:</p><div class="equation">$$\mathbb E_{p_N}[f]=\sum_iw_if(x_i).$$</div><p>For \(f(x)=x\), this is the mean. For \(f(x)=x^2\), it is the second moment. For \(f(x)=\mathbf1_{x>0}\), it is the probability of a positive position. The symbol \(\mathbf1\) means an indicator: one when its condition is true, zero otherwise.</p>`},
{id:'two-points',title:'A complete example with two particles',html:example('A target is either left or right',raw`<p>Let the positions be \([-1,1]\) and the weights be \([0.25,0.75]\). These are probabilities, not counts.</p>${table(['Question','Calculation','Answer'],[['Mean position','0.25 × (−1) + 0.75 × 1','0.5'],['Second moment','0.25 × 1 + 0.75 × 1','1'],['Variance','Second moment − mean² = 1 − 0.25','0.75'],['Probability of being right','Add weights where x &gt; 0','0.75']])}<p>One equally weighted output is \([0.5-\sqrt{0.75},0.5+\sqrt{0.75}]\), or about \([-0.366,1.366]\). It has mean 0.5 and variance 0.75. But only one of its two points is right of zero, so its right-side probability is 0.5. Matching two moments did not preserve every answer.</p>`)},
{id:'contract-lab',title:'Change the question and test the claim',lab:'contract',html:`<p>Change the target right-side probability below. The lab calculates the weighted input and an equally weighted affine output. Watch which errors stay at zero and which do not.</p>`},
{id:'three-claims',title:'Turn the research goal into three claims',html:`<p>We want an explicit, differentiable resampler that gives useful estimates. Each word needs its own test.</p>${table(['Claim','Meaning','Evidence needed'],[['Explicit construction','A stated matrix formula without solving a particle transport optimization problem.','Derive the formula and count its operations; measure actual time.'],['Differentiable map','Small input changes have a well-defined first-order effect in the stated domain.','Compare derivatives with finite differences; test repeated and small eigenvalues.'],['Useful uncertainty','The changed representation supports the questions required by the task.','Test nonlinear expectations, distribution shape, filtering error, and calibration.']])}<p>A <strong>mathematical guarantee</strong> follows from stated assumptions. An <strong>empirical result</strong> describes measured cases. A <strong>hypothesis</strong> is an open claim to investigate. These are different levels of evidence.</p>`},
{id:'metrics-and-task',title:'Why these metrics follow from the principle',html:bridge('Did we preserve the required answers?','Mean and covariance errors test the promised moments. Nonlinear expectation error, W1, and mode-mass error test answers that two moments do not determine.','Start with a fixed cloud. Then use a Gaussian mixture, where separate peaks encode different explanations.')+`<p>The current eigen map guarantees mean and population covariance matching only at full rank with inactive regularization. It does not establish novelty, universal speed superiority, unbiased filtering likelihoods, or arbitrary distribution preservation.</p><p>Next: <a href="#/eigen">derive the map</a>. For a copying-method comparison, inspect ${repo('particles','particles/resampling.py')} and ${repo('stonesoup','docs/tutorials/sampling/ResamplingTutorial.py')}.</p>`}
],quiz:{prompt:'Our two-point output has the correct mean and variance. Which further claim remains untested?',options:['It has the correct mean.','It preserves every nonlinear probability question.','Its output has two particles.'],answer:1,explanation:'The right-side probability changed from 0.75 to 0.5. Two moments do not determine every expectation.'},sources:['douc','ot','stop']},
{id:'eigen',group:'DESIGN THE METHOD',title:'Build the eigen method',subtitle:'Derive the scalar map before using matrices.',goal:'Calculate the transformation by hand, extend it to vectors, and state its exact conditions.',sections:[
{id:'scalar',title:'First principle: control center and spread',html:raw`<p>A shift changes the center of a cloud. Multiplication changes its spread. For a scalar random variable \(X\), constants \(a,b\) give:</p><div class="equation">$$\operatorname{mean}(aX+b)=a\operatorname{mean}(X)+b,$$$$\operatorname{Var}(aX+b)=a^2\operatorname{Var}(X).$$</div><p>So we first subtract the original center. Next, divide by the original standard deviation to get variance one. Multiply by the desired standard deviation. Finally, add the desired center. Standard deviation is the positive square root of variance.</p>`},
{id:'hand-calculation',title:'Do all four steps by hand',html:example('Turn [−1, 1] into the required moments',raw`<p>The input positions are \([-1,1]\), with target weights \([0.25,0.75]\). The unweighted input mean is zero and its population variance is one. The weighted target mean is 0.5 and variance is 0.75.</p>${table(['Step','Calculation','Positions / result'],[['Center','Subtract the unweighted mean 0','[−1, 1]'],['Whiten','Divide by source SD 1','[−1, 1]'],['Color','Multiply by target SD √0.75','[−0.866…, 0.866…]'],['Shift','Add target mean 0.5','[−0.366…, 1.366…]'],['Check','Average the two positions; average squared distance from 0.5','Mean 0.5; variance 0.75']])}<p>This map uses all input positions. It does not draw ancestor indices. Here “color” is the usual matrix term for adding a specified covariance.</p>`)},
{id:'vectors',title:'From a number to a covariance matrix',html:raw`<p>A vector stores several coordinates of one particle. For example, a location has horizontal and vertical coordinates. A <span data-term="covariance">covariance</span> matrix records spread in each direction and joint variation between directions.</p><p>A diagonal covariance \(\operatorname{diag}(4,1)\) has standard deviations 2 and 1. Its symmetric square root is \(\operatorname{diag}(2,1)\). The inverse root is \(\operatorname{diag}(1/2,1)\): it removes those scales. For a tilted cloud, eigenvectors give the spread directions and eigenvalues give their variances.</p><p>For a symmetric positive-definite matrix:</p><div class="equation">$$C=Q\Lambda Q^\top,\quad C^{1/2}=Q\Lambda^{1/2}Q^\top.$$</div><p>The columns of \(Q\) are unit eigenvectors; \(\Lambda\) is the diagonal matrix of positive eigenvalues. Multiplying in this order rotates into those directions, changes their scales, and rotates back.</p>`},
{id:'construction',title:'Write the complete matrix map',html:raw`<p>Let \(X\in\mathbb R^{N\times d}\) store \(N\) particles as rows, each with \(d\) coordinates. The unweighted center is \(\bar x=N^{-1}\sum_i x_i\). The target center and covariance use the normalized weights:</p><div class="equation">$$\mu_w=\sum_iw_ix_i,\qquad C_w=\sum_iw_i(x_i-\mu_w)(x_i-\mu_w)^\top.$$</div><p>Define \(Z=X-\mathbf1\bar x^\top\), where \(\mathbf1\) is a column of \(N\) ones, and \(C_0=Z^\top Z/N\). The equally weighted output is:</p><div class="equation">$$Y=\mathbf1\mu_w^\top+ZC_0^{-1/2}C_w^{1/2}.$$</div><p>This uses population covariance, with divisor \(N\). It has no Bessel sample correction.</p>`},
{id:'transform',title:'Explore center, whiten, color, and shift',lab:'eigen',html:`<p>Start at “Input.” Select each stage in order. At “Whiten,” inspect the covariance: its diagonal should be one and its off-diagonal entries zero, up to numerical error. At “Shift,” compare the final moment errors with zero.</p>`},
{id:'proof',title:'Explain why the map works',html:raw`<p>The rows of \(Z\) average to zero. A linear transformation keeps that average at zero. The final shift therefore gives mean \(\mu_w\).</p><details><summary>Derive the covariance identity</summary><p>Set \(A=C_0^{-1/2}C_w^{1/2}\). For row particles, transforming \(Z\) into \(ZA\) gives covariance \(A^\top C_0A\). Thus:</p><div class="equation">$$\operatorname{Cov}(Y)=C_w^{1/2}C_0^{-1/2}C_0C_0^{-1/2}C_w^{1/2}=C_w.$$</div><p>Keep matrix factors in this order. Matrix multiplication is generally not commutative.</p></details>`},
{id:'conditions',title:'Know when the identity can fail',html:raw`<p>Full affine rank requires at least \(N\geq d+1\). It also requires that the centered points span all \(d\) directions. If all 2D particles lie on a line, their covariance is singular: no ordinary inverse root exists.</p><p>The code replaces covariance eigenvalues below \(10^{-10}\) with this positive floor. The computation stays finite, but the exact moment identity may change. Derivatives at a floor crossing need separate treatment.</p><p>“Closed form” here means an explicit matrix construction without a particle transport optimization loop. Numerical eigendecomposition still requires computation. Arithmetic cost is O(Nd²+d³); storage is O(Nd+d²). These counts motivate timing tests but do not prove that every framework implementation is faster.</p>`},
{id:'test-and-source',title:'Measure the property you derived',html:bridge('Does the implemented map obey the algebra?','Calculate mean error and covariance Frobenius error on a full-rank fixed cloud. Add singular and nearly singular inputs to check the stated limits.','Use Gaussian clouds in dimensions 1, 2, and 4, then a mixture to separate moment correctness from shape fidelity.')+`<p>Download <a href="downloads/eigen.py" download>the actual PyTorch implementation</a>. For a different Gaussian moment-matching method, inspect ${repo('pfjax','src/pfjax/particle_resamplers.py')}. A Gaussian draw and the deterministic affine map share a moment-based idea, but they produce different finite outputs.</p>`}
],quiz:{prompt:'All 100 particles in a 2D cloud lie on one line. Does N ≥ d+1 guarantee an invertible covariance?',options:['Yes, because 100 exceeds 3.','No; the cloud lacks spread in a second direction.','Only if the weights are equal.'],answer:1,explanation:'Particle count is necessary but insufficient. The centered cloud must span the full coordinate space.'},sources:['higham','eigh','pfjax']},
{id:'limits',group:'DESIGN THE METHOD',title:'Test its limits',subtitle:'Ask a question that two moments cannot answer.',goal:'Construct a distribution counterexample and choose metrics that detect its error.',sections:[
{id:'first-principle',title:'First principle: different questions need different information',html:raw`<p>A mean compresses many possible states into one number. Variance adds a measure of spread. Neither records the full arrangement of probability mass. A <span data-term="mode">mode</span> is a local density peak. Two modes can represent two plausible explanations of an observation, such as two target locations.</p><p>The affine map applies one shift and one linear transformation to every point. It cannot independently assign a new number of equal-weight particles to each original group. This is a structural limit, not a numerical failure.</p>`},
{id:'counterexample',title:'Calculate a nonlinear error exactly',html:example('The third moment reveals a changed answer',raw`<p>Reuse positions \([-1,1]\) and weights \([0.25,0.75]\). Ask \(f(x)=x^3\), rather than just \(f(x)=x\).</p><div class="equation">$$\mathbb E_{p_N}[X^3]=0.25(-1)^3+0.75(1)^3=0.5.$$</div><p>The affine output is \(Y=0.5\pm\sqrt{0.75}\) with equal probabilities. Expanding the cube cancels its odd centered terms:</p><div class="equation">$$\mathbb E[Y^3]=0.5^3+3(0.5)(0.75)=1.25.$$</div><p>The signed expectation error is 1.25 − 0.5 = 0.75. Its squared error is 0.5625. Mean and variance errors are zero. All three statements can be true together.</p>`)},
{id:'mixture',title:'See the same issue with two visible peaks',lab:'mixture',html:`<p>Keep the output method at “Eigen affine.” Set right-mode mass to 0.5, then 0.9. The input has equal numbers of particles in each group; weights change the desired probability. Watch the peaks move and compare the moment errors with W1 and MMD².</p><p>Next choose “Multinomial draw.” It changes group counts by copying ancestors. Its answers are unbiased over repeated draws, although one draw has sampling error. A “Gaussian draw” can erase the separated shape even when its generating Gaussian has the target moments.</p>`},
{id:'which-metric',title:'Why a shape metric is needed',html:bridge('Did probability move to the wrong places?','W1 measures probability movement; MMD compares kernel features; nonlinear expectation error tests a specific question; mode-mass error checks the allocation between explanations.','Use separated Gaussian mixtures, UNGM sign ambiguity, or bearing tracking with competing positions.')+example('Mode survival is too weak by itself',`<p>Suppose the target puts 90% mass in the right peak and 10% in the left. An output with 50% in each still contains both peaks. Its mode-survival score can be perfect while its right-mode mass error is |0.5 − 0.9| = 0.4.</p><p>This is why we measure both survival and mass. In our actual suite, a mixture neighborhood lies within radius 1.35 of a center at −3 or +3. It counts as covered when its mass exceeds 1%. The reported halfspace mass error uses x &lt; 0. These are fixed local definitions, not universal thresholds.</p>`)},
{id:'failure-design',title:'Use the counterexample to guide the next design',html:`<p>If the claim is “preserve two moments,” the counterexample is consistent with it. If the claim is “preserve arbitrary distributions,” the same example disproves it. A stronger design might treat modes separately or move particles using a transport objective. Each proposal needs its own probability contract and gradient analysis.</p><p>Entropy-regularized optimal transport gives a smooth numerical coupling. It introduces regularization and numerical solver costs. It does not make every finite-particle bias disappear. Compare its shape, gradient, filtering, and cost results on the same inputs.</p><p>Use ${repo('particles','book/resampling/compare_tv_distance_resampling.py')} for a native weighted-cloud comparison, and ${repo('pfjax','src/pfjax/particle_resamplers.py')} or ${repo('pydpf','pydpf/pydpf/resampling.py')} for transport baselines. Continue to <a href="#/metrics">the metric worked examples</a> to calculate W1 directly.</p>`}
],quiz:{prompt:'A two-mode output keeps both modes but assigns 50% mass to each instead of 10% and 90%. Which score exposes this directly?',options:['Mode survival alone.','Mode-mass error.','The number of output particles.'],answer:1,explanation:'Both modes survive, but the probability allocation is wrong by 0.4 in the right group.'},sources:['mmd','ot','book']},
{id:'gradients',group:'DESIGN THE METHOD',title:'Understand gradients',subtitle:'Start with a slope, then identify the probability objective.',goal:'Calculate a derivative, check it numerically, and distinguish that check from likelihood-gradient accuracy.',sections:[
{id:'slope',title:'First principle: a derivative is local sensitivity',html:raw`<p>Suppose \(\theta\) is a model parameter, such as observation noise. An objective \(J(\theta)\) assigns a number to a parameter choice. Its derivative answers: “For a small parameter change, how much does this number change?”</p><div class="equation">$$J'(\theta)=\lim_{h\to0}\frac{J(\theta+h)-J(\theta)}{h}.$$</div><p>For several parameters, collect the partial derivatives into a <span data-term="gradient">gradient</span> vector. An optimizer can use this vector to improve its objective. That only helps if we differentiate the objective we actually intend to optimize.</p>`},
{id:'hand-slope',title:'Check a derivative with numbers',html:example('One function, one slope',raw`<p>Let \(J(\theta)=\theta^2\) and \(\theta=2\). Algebra gives \(J'(2)=4\). With \(h=0.01\), a central finite difference gives:</p><div class="equation">$$\frac{J(2.01)-J(1.99)}{0.02}=\frac{4.0401-3.9601}{0.02}=4.$$</div><p>For general smooth functions, this is an approximation. A large step introduces truncation error. An extremely small step can lose precision when two nearby numbers are subtracted. Try several step sizes; agreement at one step alone is weak evidence.</p>`)},
{id:'targets',title:'Name three different derivative targets',html:raw`<p>Our fixed particles \(x_i\) get weights \(w_i(\theta)\). Define:</p><div class="equation">$$F(\theta)=\sum_iw_i(\theta)f(x_i),\qquad G(\theta)=\frac1N\sum_jf(y_j(\theta)).$$</div><p>\(F\) is the original weighted answer. \(G\) is the answer after the affine map. Automatic differentiation can correctly calculate \(G'\) while \(G'\) differs from \(F'\). A separate target is the model’s true log-likelihood gradient, which uses a whole observation sequence.</p>${table(['Target','What is being changed?','Suitable check'],[['Derivative of the implemented map / surrogate G','The actual operations in our code.','Compare analytic or automatic derivatives with finite differences of the same G.'],['Derivative of weighted answer F','The target finite empirical expectation.','Compare G′ with a direct derivative of F.'],['True likelihood score','The probability density of all observed data under the model.','Compare PF scores with an exact Kalman score, or a stated approximate nonlinear reference.']])}`},
{id:'two-point-gradient',title:'A complete two-particle derivative example',html:example('Correct derivative, different target',raw`<p>Take \(x=[-1,1]\), and define \(w_i(\theta)=\exp(\theta x_i)/\sum_k\exp(\theta x_k)\), called softmax weights. The weighted mean is \(\mu=\tanh\theta\) and variance is \(1-\mu^2\).</p><p>For \(f(x)=x^3\), the original answer is \(F=\mu\). The affine answer is \(G=\mu^3+3\mu(1-\mu^2)=3\mu-2\mu^3\).</p><div class="equation">$$F'=(1-\mu^2),\qquad G'=(3-6\mu^2)(1-\mu^2).$$</div><p>At \(\theta=0\), both objectives equal zero, yet \(F'=1\) and \(G'=3\). Even agreement of the two objective values at one point does not imply equal slopes.</p>`)},
{id:'experiment',title:'Compare objectives, slopes, and finite differences',lab:'gradient',html:`<p>This lab uses more particles and softmax weights. Start with sin(x): compare the original objective F with the affine objective G. Then compare G′ with its own finite difference. Finally choose x², an expectation fixed by the matched moments. Observe why target agreement improves for that function.</p>`},
{id:'root',title:'Why matrix derivatives need care',html:raw`<p>A covariance can have repeated eigenvalues. Eigenvectors inside that repeated eigenspace are not unique. Differentiating a chosen eigenvector basis can be unstable even when the matrix square-root function itself has a valid derivative.</p><p>Our backward calculation differentiates the <em>matrix function</em>. For a positive-definite covariance, this avoids dividing by a difference of nearly equal eigenvalues.</p><details><summary>Derive the first-order square-root derivative</summary><p>Let \(S=C^{1/2}\), so \(S^2=C\). A perturbation \(H\) of \(C\) produces a first-order perturbation \(L\) of \(S\). Expanding \((S+L)^2\) and dropping the second-order term \(L^2\) gives \(SL+LS=H\), a Sylvester equation. In an eigenvector basis:</p><div class="equation">$$L_{ij}=\frac{H_{ij}}{\sqrt{\lambda_i}+\sqrt{\lambda_j}}.$$</div><p>The inverse-root derivative multiplies each basis entry of \(H\) by:</p><div class="equation">$$-\frac1{\sqrt{\lambda_i}\sqrt{\lambda_j}(\sqrt{\lambda_i}+\sqrt{\lambda_j})}.$$</div><p>Equal positive eigenvalues are safe in these formulas. Very small eigenvalues can amplify derivatives. Clipped eigenvalues require divided differences and have floor-crossing kinks. Our custom implementation supports first-order differentiation only.</p></details>`},
{id:'score-metrics',title:'From local slopes to useful learning',html:bridge('Does the random likelihood gradient estimate point toward the intended objective?','Bias measures systematic slope error. Variance measures run-to-run noise. MSE combines both. Finite-difference error checks implementation consistency, a different property.','Use a linear Gaussian model with an exact Kalman derivative, then stochastic-volatility scale fitting.')+`<p>A <strong>likelihood</strong> is the observation density as a function of model parameters. Its log turns products across time into sums. The derivative of that log is the <strong>score</strong>. Classical ancestor selection is discrete; treating selected indices as constants does not generally produce the intended score. A stop-gradient correction changes the backward rule while retaining the forward filter.</p><p>Follow <a href="${references.cuthbert[1]}" target="_blank" rel="noopener noreferrer">Cuthbert’s differentiable-resampling tutorial</a> and its ${repo('cuthbert','docs/examples/diff_pf_resampling.md')} source. Our native comparison uses 800 Cuthbert trials and 84 profile evaluations, plus 2,440 PyTorch trials on the same saved linear data. These are controlled model results, not proof of universal learning quality.</p>`}
],quiz:{prompt:'Finite differences confirm G′ = 3, but the intended target has F′ = 1. What should you conclude?',options:['The implementation derivative may be correct, but the target derivative is wrong by 2.','Finite differences establish an accurate likelihood score.','The two objectives must be equal everywhere.'],answer:0,explanation:'A derivative check must name its objective. Correctly differentiating a surrogate does not make that surrogate the intended target.'},sources:['cuthbert','stop','higham','eigh']},
{id:'metrics',group:'TEST THE CLAIM',title:'Choose metrics',subtitle:'Derive a measurement from the question it must answer.',goal:'Calculate the main metrics on small examples and choose them for different tasks.',sections:[
{id:'first-principle',title:'First principle: define the reference and the question',html:`<p>A metric is a numerical rule for measuring a property. Before choosing one, state the reference: the input weighted distribution, the true simulated state, an exact posterior, or a reference derivative. “Error” is incomplete unless we say error relative to what.</p>${table(['Question','Reference','Metric'],[['Did the center and spread change?','Weighted input moments.','Mean and covariance errors.'],['Did probability move to the wrong places?','Weighted input measure.','W1, MMD², nonlinear expectation error, and mode mass.'],['Did the filter track the state and express uncertainty honestly?','Simulated truth; exact posterior where available.','RMSE, coverage, and posterior error.'],['Did we obtain a useful learning signal?','Exact or stated approximate score.','Gradient bias, variance, and MSE.'],['What does the accuracy cost?','Same task, count, hardware, and timing boundary.','Time, memory, and failure rate.']])}<p>Lower error is usually better. Coverage has a target, such as 0.95; higher is not always better. ESS describes weights and is not an accuracy score.</p>`},
{id:'moment-errors',title:'Start with center, spread, and a test function',html:raw`<p>For an output mean \(\widetilde\mu\) and target mean \(\mu_w\), mean error is \(\|\widetilde\mu-\mu_w\|_2\). The norm \(\|\cdot\|_2\) is Euclidean distance. Covariance error is \(\|\widetilde C-C_w\|_F\). The Frobenius norm takes the square root of the sum of squared matrix entries.</p>${example('Read a covariance error',raw`<p>If the target covariance is \(\operatorname{diag}(1,4)\) and the output covariance is \(\operatorname{diag}(2,2)\), their Frobenius error is \(\sqrt{(2-1)^2+(2-4)^2}=\sqrt5\approx2.236\). Units are state units squared. Sorted eigenvalue error measures directional variance sizes but can miss incorrectly rotated directions.</p><p>For a function \(f\), expectation error is \(\sum_jv_jf(y_j)-\sum_iw_if(x_i)\), where \(v_j\) are normalized output weights. Square and average this over resampling runs to get expectation MSE. Our two-particle cubic example has error 0.75 and squared error 0.5625.</p>`)}`},
{id:'w1',title:'Derive W1 from moving probability mass',html:raw`<p>Imagine each distribution as piles of probability mass. W1 is the least average travel distance needed to rearrange one into the other. In one dimension, the exact formula uses cumulative distribution functions (CDFs):</p><div class="equation">$$W_1(p,q)=\int_{\mathbb R}|F_p(z)-F_q(z)|\,dz.$$</div><p>A CDF is the probability of being at or below a position. The formula adds the area between the two CDF curves.</p>${example('Move two piles to the middle',raw`<p>Let \(p\) place half its mass at 0 and half at 2. Let \(q\) put all its mass at 1. The mean is 1 for both. Move mass 0.5 from 0 to 1, and mass 0.5 from 2 to 1. W1 = 0.5 × 1 + 0.5 × 1 = 1.</p><p>The same result follows from the CDFs: their absolute difference is 0.5 on [0,1) and 0.5 on [1,2), giving total area 1. W1 has the same units as position.</p>`)}<p>For multiple dimensions, our benchmark projects the clouds onto 16 fixed directions, computes 1D W1 in each direction, and averages. This is <strong>sliced W1</strong>, not exact multivariate W1. The browser labs use exact 1D empirical W1.</p>`},
{id:'mmd',title:'Derive MMD from comparisons of features',html:raw`<p>Two clouds might have the same mean position but different answers to curved functions of position. A kernel implicitly supplies many such features. A Gaussian kernel is \(k(a,b)=\exp(-(a-b)^2/(2\sigma^2))\), where \(\sigma\) is its bandwidth. Nearby positions have high similarity.</p><div class="equation">$$\mathrm{MMD}^2(p,q)=\mathbb E k(X,X')+\mathbb E k(Y,Y')-2\mathbb E k(X,Y).$$</div><p>\(X,X'\) are independent draws from \(p\); \(Y,Y'\) are independent draws from \(q\). The formula compares within-distribution similarity with between-distribution similarity.</p>${example('Compare two point masses',raw`<p>Put all input mass at 0 and all output mass at 2. With bandwidth \(\sigma=1\), both within terms equal 1. The between term is \(e^{-2}\). Thus MMD² = \(2-2e^{-2}\approx1.729\).</p><p>Changing bandwidth changes the score. Always report it. The browser uses the weighted input standard deviation as bandwidth, with a small floor. The main benchmark instead uses 128 fixed random Fourier features and bandwidth equal to the square root of the target covariance trace; that is a numerical approximation to kernel MMD².</p>`)}`},
{id:'metric-playground',title:'Use the metrics on three different errors',lab:'metric-playground',html:`<p>Choose a shifted cloud, an affine moment match, or collapse to the mean. Compare which metrics react. A shifted cloud preserves variance but changes its center. A collapsed cloud can preserve the center while losing uncertainty. An affine moment match can preserve both and still change shape.</p>`},
{id:'filter-error',title:'From state errors to RMSE and coverage',html:raw`<p>For estimates \(\widehat x_t\) and true states \(x_t\), scalar tracking RMSE is:</p><div class="equation">$$\operatorname{RMSE}=\sqrt{\frac1T\sum_{t=1}^T(\widehat x_t-x_t)^2}.$$</div>${example('Accuracy and confidence can disagree',`<p>For errors [1, −2, 1], mean squared error is (1 + 4 + 1)/3 = 2, so RMSE = √2 ≈ 1.414. RMSE has state units.</p><p>If a nominal 95% interval contains the truth in 9 of 10 teaching cases, observed coverage is 90%. Ten cases give a noisy estimate; they do not establish calibration. Very wide intervals can cover almost everything and still be unhelpful. Read coverage with RMSE and uncertainty size.</p>`)}<p>Our bearing task uses position error; other tasks have their stated state definitions. <strong>Posterior mean error against Kalman</strong> measures approximation of a conditional distribution; <strong>tracking error against truth</strong> measures distance from one realized state. These are different references.</p>`},
{id:'gradient-error',title:'Separate bias, variance, and MSE',html:raw`<p>Let \(g^\star\) be the reference derivative and \(g\) its random estimate. Bias is \(\mathbb E[g]-g^\star\). Variance is random spread around \(\mathbb E[g]\). For a vector score:</p><div class="equation">$$\mathbb E\|g-g^\star\|_2^2=\|\mathbb E[g]-g^\star\|_2^2+\operatorname{tr}\operatorname{Cov}(g).$$</div>${example('A quiet gradient can still be wrong',`<p>Suppose the true derivative is 2. Estimates [1,2,3] have mean 2, zero estimated bias, empirical squared error 2/3, and population-style variance 2/3. Estimates [3,3,3] have zero variation but bias 1 and MSE 1.</p><p>The benchmark reports sample-corrected variance. For [1,2,3], that sample variance is 1, not 2/3. So finite reported sample variance plus squared estimated bias need not exactly equal empirical MSE.</p>`)}<p>Repeat PF seeds on the <em>same data</em> to estimate algorithmic variation conditional on those observations. Repeat independent observation datasets to study how behavior changes across data. The full-filter confidence intervals cluster by dataset.</p>`},
{id:'cost-and-failure',title:'Use a scorecard, not one winning number',html:`<p>Suppose method A has successful-run RMSE 0.2 but fails on 30% of trials. Method B has RMSE 0.3 and completes all trials. A’s average is conditional on success; it does not establish better performance on all attempted trials. Show successful/attempted counts and failure rate.</p><p>Likewise, compare time at the same N, dimension, precision, and operation boundary. Our CPU forward timings include adapters; Julia includes IPC. JAX local gradient time includes forward and backward, while the PyTorch/TensorFlow local backward column is backward only. Process peak RSS includes imports and JIT caches, so it is not isolated per-call allocation.</p><p>For definitions in executable code, download <a href="downloads/metrics.py" download>metrics.py</a>. Use ${repo('particles','particles/kalman.py')} for a native exact reference, and <a href="#/benchmarks">the next lesson</a> to select tasks that exercise each property.</p>`}
],quiz:{prompt:'A shifted output has the same variance as its input. Which pair can reveal the displacement?',options:['Variance error and particle count.','Mean error and W1.','Mode survival and runtime alone.'],answer:1,explanation:'Variance is invariant to a common shift. Mean error detects the center change, and W1 measures the probability movement.'},sources:['mmd','douc','kalman','cuthbert']},
{id:'benchmarks',group:'TEST THE CLAIM',title:'Run benchmarks',subtitle:'Choose a task because it can expose a specific failure.',goal:'Connect six task families to probability principles, toy cases, metrics, and source implementations.',sections:[
{id:'first-principle',title:'First principle: isolate a cause before testing a system',html:`<p>A particle filter combines a state model, observation model, proposals, weighting, and resampling. If its error changes, any of these parts may be responsible. Start with fixed particles and weights to isolate resampling. Then put the same resampler inside a controlled filter.</p><p>A <strong>benchmark family</strong> is a type of test problem. These six families are not one official leaderboard. Our shared suite uses local common models so upstream resamplers receive the same inputs. Native checks separately run source models with their own defaults. Keep their results separate.</p>`},
{id:'fixed-cloud',title:'1. Fixed weighted cloud: test resampling alone',html:example('Repeat one distribution, not new data',`<p>Keep [−1,1] and weights [0.25,0.75] fixed. With N=2, a multinomial draw can copy the left point twice, copy one of each, or copy the right point twice. Repeat many seeds. Compare its average output mean with 0.5, and measure variation between draws.</p><p>For copying methods, expected left/right offspring counts are [0.5,1.5]. Measure offspring-count bias and variance. For a transform that creates new positions, these discrete offspring counts do not apply; use expectation and distribution errors.</p>`)+bridge('What error does the resampling step add, conditional on the input?','Expectation MSE, conditional offspring statistics where defined, W1/MMD, and time.','Use '+repo('stonesoup','docs/tutorials/sampling/ResamplingTutorial.py')+' and '+repo('particles','book/resampling/compare_tv_distance_resampling.py')+'.')},
{id:'gaussian-mixture',title:'2. Gaussian and mixture clouds: test shape and rank',html:`<p>A Gaussian is a single smooth peak determined by its mean and covariance. A mixture combines several component distributions. Start with one full-rank Gaussian; then use two separated peaks and uneven weights. Change dimension and weight concentration.</p>${example('Two explanations, unequal evidence',`<p>Put particles near −3 and +3. Give the right group 90% of the weight. A method can match the target center and covariance while keeping half its output points in each shifted group. Measure mode mass and W1 as well as moments.</p>`)}${bridge('Does a method preserve only moments or also the probability shape?','Mean/covariance/eigenvalue errors, sliced W1, RFF MMD², nonlinear expectation MSE, mode survival, and mass error.','Our declared shared cloud generator, <a href="downloads/models.py" download>models.py</a>; compare Gaussian/OT transforms in '+repo('pfjax','src/pfjax/particle_resamplers.py')+'.')}<p>The native particles book task evaluates weighted Gaussian resampling with its own total-variation setup. Our local mixture design is a separate test; it is not copied from an official mixture leaderboard.</p>`},
{id:'linear',title:'3. Linear Gaussian: get an exact answer',html:raw`<p>Both the state transition and observation are linear, and their noises are Gaussian. Gaussian distributions remain Gaussian under these updates, so a Kalman filter gives an exact posterior and likelihood.</p><div class="equation">$$x_t=0.8x_{t-1}+0.5\epsilon_t,\qquad y_t=x_t+0.8\eta_t,$$</div><p>The shared initial variance is 1; \(\epsilon_t,\eta_t\) are independent standard normal noises.</p>${example('One Gaussian observation update',`<p>For a teaching prior with mean 0 and variance 1, observation y=1, and observation variance 1, the Kalman gain is 1/(1+1)=0.5. The posterior mean is 0 + 0.5×(1−0)=0.5; posterior variance is (1−0.5)×1=0.5. These numbers illustrate the update; they are not the shared model’s noise setting.</p>`)}${bridge('How close is the approximation to an exact posterior and score?','Posterior mean/covariance error, likelihood error, and likelihood-gradient bias/variance/MSE; also tracking RMSE and calibration.','Native '+repo('particles','particles/kalman.py')+' and '+repo('cuthbert','docs/examples/diff_pf_resampling.md')+'.')}<p>The native Cuthbert gradient task uses a random-walk model with process SD 0.4 and observation SD 0.8. It is a separate model from the shared AR(1) task above.</p>`},
{id:'ungm',title:'4. Nonlinear growth: preserve ambiguity',html:raw`<p>The univariate nonlinear growth model (UNGM) uses a nonlinear transition and a squared observation:</p><div class="equation">$$x_t=0.5x_{t-1}+\frac{25x_{t-1}}{1+x_{t-1}^2}+8\cos(1.2t)+\sqrt{10}\epsilon_t,$$$$y_t=x_t^2/20+\eta_t.$$</div>${example('An observation cannot reveal the sign',raw`<p>States \(x=2\) and \(x=-2\) both predict observation mean \(4/20=0.2\). With the same observation noise, the likelihood alone cannot distinguish them. A filter may need to retain both explanations until later observations resolve them.</p>`)}${bridge('Does the filter retain plausible alternatives under nonlinear observations?','State RMSE, coverage, predictive negative log density, and repeated-seed likelihood variation. Use mixture tests to diagnose shape changes separately.','Native Gordon_etal in '+repo('particles','particles/state_space_models.py')+'.')}<p>Predictive negative log density is −log of the density assigned to the next observation. A continuous density can exceed one, so this value can be negative. Native Gordon defaults use a different initial variance and time offset from our shared task. There is no exact Kalman reference for this nonlinear model.</p>`},
{id:'volatility',title:'5. Stochastic volatility: test uncertainty and learning',html:raw`<p>The hidden state changes observation variance rather than observation mean:</p><div class="equation">$$x_t=0.95x_{t-1}+0.2\epsilon_t,\qquad y_t=s\exp(x_t/2)\eta_t.$$</div><p>The true shared observation scale is \(s=1\).</p>${example('The same zero mean, a different risk',raw`<p>At \(x_t=0\) and \(s=1\), observation SD is 1. At \(x_t=\log4\), SD is 2 and variance is 4. Both observation distributions have mean zero. A mean-only metric misses the change in risk.</p>`)}${bridge('Are uncertainty and the parameter-learning signal useful?','Filtering RMSE/coverage, likelihood-score error, and fitted-scale error. Compare to the stated numerical grid-filter reference.','Native StochVol in '+repo('particles','particles/state_space_models.py')+' and learning examples in '+repo('pydpf','replication_materials')+'.')}<p>Our learning run uses 10 datasets and a five-value scale grid {0.6,0.8,1,1.2,1.4}. It tests discrete scale selection, not convergence of a continuous optimizer. The grid-filter reference is approximate.</p>`},
{id:'bearing',title:'6. Bearing-only tracking: test missing data and recovery',html:raw`<p>A sensor measures direction, not distance. The shared state stores [px,vx,py,vy] for a 2D constant-velocity target. Angle noise has SD 0.05 radians:</p><div class="equation">$$y_t=\operatorname{atan2}(p_y,p_x)+0.05\eta_t.$$</div>${example('One angle, several locations',`<p>Positions (1,1) and (2,2) both have a 45° bearing from the origin. Motion and later observations help infer distance. If observations disappear, the filter must propagate uncertainty until they return.</p>`)}${bridge('Can the filter keep uncertainty and regain tracking after a gap?','Position RMSE, coverage, post-gap RMSE, recovery steps, and recovery fraction.','Native BearingsOnly in '+repo('particles','particles/state_space_models.py')+'; the separate moving-sensor example in '+repo('stonesoup','docs/examples/filters/bearing_only_example.py')+'.')}<p>The shared gap omits zero-based observations 20–29. Native particles has a different model, state order [vx,vy,px,py], and no gap. Stone Soup’s separate example uses an extended Kalman filter (EKF); it is a source-task smoke check, not a resampler ranking.</p>`},
{id:'choose-task',title:'Choose a task from the claim',lab:'task-guide',html:`<p>Select the property you want to test. The guide gives a small starting example, the reference, metrics, and a pinned source. A task is useful because of the question it can answer.</p>`},
{id:'protocol',title:'Build a fair comparison in six steps',html:`<ol class="steps"><li><strong>Freeze inputs.</strong> Save observation datasets, cloud seeds, models, and source revisions.</li><li><strong>Keep one comparison layer.</strong> Compare shared models with shared models; native checks with the same native task.</li><li><strong>Use the actual output weights.</strong> Soft resampling can retain importance-correction weights. Equal-weight formulas do not automatically apply.</li><li><strong>Repeat the right randomness.</strong> Resampling seeds on fixed clouds; PF seeds within datasets; independent datasets for data variation.</li><li><strong>Keep failures visible.</strong> Report attempted and successful counts. Accuracy summaries condition on successful trials.</li><li><strong>Measure cost separately.</strong> Warm up, synchronize, and use a serial timing pass with documented boundaries.</li></ol><p>The completed main grid uses N={32,128,512,2048}; fast methods use 100 repeats and 50-step filters. Costly OT/Gumbel grids are smaller: full filters at N≤128 and one PF seed per dataset; large-N static cases use three repeats. Corrected FilterFlow OT is limited to N≤128. Dense OT at N=2048 has a sparse scaling case. All measurements are CPU-only.</p>`}
],quiz:{prompt:'Which task should you start with when you need an exact likelihood-gradient reference?',options:['Linear Gaussian with a Kalman reference.','Bearing-only tracking with an observation gap.','A single static mixture draw.'],answer:0,explanation:'The linear Gaussian model gives an exact likelihood and differentiable Kalman reference. Nonlinear tasks need other stated references.'},sources:['models','kalman','stone','book','cuthbert','pydpf']},
paperResultLesson(),
{id:'resources',group:'REFERENCE',title:'Read and reproduce',subtitle:'Follow a question from its principle to its source and a small run.',goal:'Find the right paper or repository, distinguish native from shared tasks, and reproduce a bounded example.',sections:[
{id:'first-principle',title:'First principle: a source must support a specific statement',html:`<p>A paper explains assumptions and a result. A repository supplies an implementation. A benchmark run measures that implementation under particular settings. These support different kinds of statements. A source link alone is not proof that our local method has the paper’s guarantee.</p><p>Start with a question you understand, such as “does the output preserve a cubic expectation?” Then find the relevant derivation, implementation, and experiment. Record the source revision so later changes do not silently change the test.</p>`},
{id:'reading',title:'Read the literature in question order',html:table(['Question to carry into the reading','Source','What to look for'],[
['What do copying methods preserve on average?',`<a href="${references.douc[1]}" target="_blank" rel="noopener noreferrer">Douc, Cappé & Moulines · resampling comparison</a>`,'Conditional unbiasedness, variance assumptions, and systematic-order effects.'],
['How can I compare full distributions beyond moments?',`<a href="${references.mmd[1]}" target="_blank" rel="noopener noreferrer">Gretton et al. · kernel two-sample testing</a>`,'Kernel features, bandwidth, and the distinction between population and empirical quantities.'],
['Can particle movement have a smooth transport construction?',`<a href="${references.ot[1]}" target="_blank" rel="noopener noreferrer">Corenflos et al. · entropy-regularized OT particle filtering</a>`,'The actual transport objective, regularization, and the assumptions of the convergence analysis.'],
['Can the forward filter stay unchanged while its derivative rule changes?',`<a href="${references.stop[1]}" target="_blank" rel="noopener noreferrer">Ścibior & Wood · differentiable filtering</a>`,'The backward correction and its statistical target.'],
['How is a discrete choice relaxed continuously?',`<a href="${references.gumbel[1]}" target="_blank" rel="noopener noreferrer">Jang, Gu & Poole · Gumbel-softmax</a>`,'Temperature and the relaxed sampling objective; relaxation is not an automatic PF score guarantee.'],
['Why can a matrix root be differentiable at repeated positive eigenvalues?',`<a href="${references.higham[1]}" target="_blank" rel="noopener noreferrer">Higham · Sylvester equation</a>`,'Differentiate the matrix function rather than an arbitrary eigenvector basis.']])+`<p>The affine map is a moment-matching baseline. This list gives context, not a novelty claim. A new-method claim needs a broader comparison with prior ensemble transforms and precise statements of what differs.</p>`},
{id:'repo-map',title:'Which repository helps with which question?',html:table(['Repository','Use it for','How this project uses it'],[
[repo('particles'),'Classical resamplers, native state-space models, Kalman references, book examples.','Shared resampler adapters; 2,880 native model trials; 8,400 reduced native book trials.'],
[repo('stonesoup'),'Readable resampling and tracking examples.','Shared adapters; native resampling tutorial and separate bearing EKF smoke check.'],
[repo('cuthbert'),'Differentiable resampling and PF-versus-Kalman score experiments.','Shared adapters; 800 native gradient trials and 84 profile evaluations.'],
[repo('pfjax'),'JAX particle filtering, Gaussian matching, and OT resampling.','Shared adapters; selected upstream tests; a source of implementation examples.'],
[repo('pydpf'),'PyTorch resampling and differentiable-filter replication examples.','Shared adapters; bounded native replication checks, smaller than paper-scale runs.'],
[repo('torchfilter'),'PyTorch filters and soft resampling with corrected weights.','Shared adapters and selected upstream tests.'],
[repo('filterflow'),'TensorFlow transport and covariance-corrected resampling.','Shared adapters; 30 native full-model attempts; selected tests with four recorded failures.'],
[repo('julia'),'Classical resampling algorithms in Julia.','Shared adapters through IPC; 1,803 selected upstream assertions.']
])+`<p>“Shared adapter” means our local harness calls the source resampler on common inputs. “Native task” means the source model or example is run under its declared settings. A native EKF check does not benchmark PF resampling; a selected test run is not every test in the repository.</p>`},
{id:'repos',title:'Check the exact pinned revisions',html:`<p>These links open the exact checked-out commits. Keep the revision with every reproduced measurement.</p><div id="repo-list" class="repo-list"></div><p>For guided usage, start with <a href="${references.cuthbert[1]}" target="_blank" rel="noopener noreferrer">Cuthbert’s differentiable-resampling tutorial</a> and <a href="${references.pfjax[1]}" target="_blank" rel="noopener noreferrer">PFJAX documentation</a>. The requested PFJAX GitHub Pages URL did not load during the original verification; Read the Docs is the working reference used here.</p>`},
{id:'worked-plan',title:'A complete small experiment plan',html:example('Test one stronger claim before adding complexity',`<p><b>Claim:</b> the affine map preserves a cubic expectation. <b>Input:</b> [−1,1] with weights [0.25,0.75]. <b>Reference:</b> weighted cubic expectation 0.5. <b>Method:</b> the equal-weight affine output [−0.366…,1.366…]. <b>Metric:</b> absolute cubic expectation error. <b>Result:</b> |1.25−0.5|=0.75, so this stronger claim fails.</p><p><b>Keep the valid result:</b> mean and variance still match. <b>Next experiment:</b> use the same metric on a saved mixture cloud and a classical or transport comparator. <b>Then:</b> run the linear filter with an exact reference before moving to nonlinear state models.</p>`)+`<p>This sequence gives each experiment a reason. It also lets another person reproduce the counterexample without first installing eight frameworks.</p>`},
{id:'run',title:'Run a bounded example from the project',html:raw`<p>From the project folder, restore the pinned environments if needed. Setup requires uv and the CPU dependencies listed in the project README. The smoke profile is deliberately small: N=32, three repeats, 12-step filters, and static dimensions 1 and 2. It checks that the workflow runs; it does not estimate precise performance.</p><pre><code># Only when the pinned environments need setup
python scripts/setup.py

# First check the mathematical implementation
PYTEST_DISABLE_PLUGIN_AUTOLOAD=1 .venv/bin/python -m pytest -q

# Run a small eigen example; use a fresh output directory
OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 .venv/bin/python \
  -m resampler_bench.run --provider custom --methods eigen \
  --profile smoke --stages static filter gradient \
  --output results/eigen-lesson-new</code></pre><p>Inspect the raw static, filter, and gradient CSVs plus status.jsonl in that directory. Record which reference each metric uses. Raw trials differ from the aggregated summary CSVs shown on this site. Increase the grid only after the small run is understandable.</p><details><summary>Extend to native source tasks</summary><pre><code>.venv/bin/python scripts/check_upstream_tasks.py \
  --output results/native-lesson-new</code></pre><p>This command is broader than the smoke example. It includes bounded native tasks and selected upstream tests. It continues through failing tests and reports a nonzero exit status when failures remain. Read the recorded outcomes; do not treat that status alone as missing task coverage.</p></details>`},
{id:'downloads',title:'Trace equations and numbers back to files',html:`<div class="download-grid"><a href="downloads/eigen.py" download>Affine map and backward rule <span>PY ↓</span></a><a href="downloads/models.py" download>Shared clouds and state models <span>PY ↓</span></a><a href="downloads/metrics.py" download>Metric definitions <span>PY ↓</span></a><a href="downloads/static_summary.csv" download>Measured static summaries <span>CSV ↓</span></a><a href="downloads/PROJECT-README.md" download>Environment and full scope <span>MD ↓</span></a><a href="downloads/sources.lock.json" download>Exact repository revisions <span>JSON ↓</span></a><a href="downloads/BENCHMARK-REPORT.md" download>Full measured report <span>MD ↓</span></a><a href="downloads/NATIVE-CHECKS.md" download>Native checks and failures <span>MD ↓</span></a></div>`},
{id:'glossary',title:'Keep definitions close to the example',html:`<p>Underlined terms in earlier lessons open a short definition. Use this list when reading papers or source code.</p><div class="glossary-list">${Object.entries(glossary).map(([term,definition])=>`<details><summary>${term}</summary><p>${definition}</p></details>`).join('')}</div>`},
{id:'next',title:'Build the next method around a testable question',html:`<p>Choose one stronger property, such as preserving unequal mode mass with useful first-order gradients. State its assumptions, build a counterexample for the current baseline, and propose a change. Then test moment accuracy, shape, implementation derivatives, likelihood scores, calibration, and cost on saved common inputs.</p><p>A simple baseline is useful when its guarantees and limits are clear. Keep it as a comparator while you test the next idea.</p>`}
],quiz:{prompt:'A source tutorial runs, but its model differs from the shared suite. Where should its result go?',options:['Into the shared ranking as if all inputs were identical.','Into a labeled native-task result with its own model and settings.','Nowhere; source examples cannot be useful.'],answer:1,explanation:'Native checks verify source workflows. Shared rankings require common inputs, models, and metrics.'},sources:['douc','ot','stop','cuthbert','pfjax','models']}
];}
